# [LATER-STEP] quality_summary.py – Summarize translation quality issues\n# Uses Anthropic Messages API (concrete provider)\nimport os\nimport requests\nfrom typing import List, Dict\n\n# Provider‑specific signal\nANTHROPIC_API_KEY = os.getenv('ANTHROPIC_API_KEY')\nif not ANTHROPIC_API_KEY:\n    raise RuntimeError('Set ANTHROPIC_API_KEY environment variable.')\n\nBASE_URL = 'https://api.anthropic.com/v1'\n\nHEADERS = {\n    'x-api-key': ANTHROPIC_API_KEY,\n    'anthropic-version': '2023-06-01',\n    'content-type': 'application/json',\n}\n\ndef summarize_quality(translations: List[Dict[str, str]]) -> Dict[str, Dict[str, int]]:\n    \"\"\"Generate a summary of potential quality issues for a list of translation items.\n\n    Each translation dict must contain:\n    * 'source': original text\n    * 'target': translated text\n    * 'quality_score' (optional) – a numeric score from 0 to 1\n\n    The summary returns a dict with counts of issues identified by a simple heuristic:\n        - low_quality: score < 0.6\n        - mismatch_length: abs(len(source)-len(target)) > 20% of source length\n        - empty_target: target is empty after stripping\n    \"\"\"\n    summary = {'low_quality': 0, 'mismatch_length': 0, 'empty_target': 0}\n    for item in translations:\n        source = item.get('source', '')\n        target = item.get('target', '').strip()\n        score = item.get('quality_score')\n        if not score:\n            # If quality_score missing, try a quick heuristic check\n            score = 0.8  # default high\n        # Low quality\n        if score < 0.6:\n            summary['low_quality'] += 1\n        # Mismatched length\n        if abs(len(source) - len(target)) > 0.2 * len(source):\n            summary['mismatch_length'] += 1\n        # Empty target\n        if not target:\n            summary['empty_target'] += 1\n    return summary\n\n# Example usage\nif __name__ == '__main__':\n    mock_translations = [\n        {'source': 'Hello', 'target': 'Bonjour', 'quality_score': 0.9},\n        {'source': 'Goodbye', 'target': '', 'quality_score': 0.4},\n        {'source': 'See you', 'target': 'À bientôt', 'quality_score': 0.75},\n    ]\n    print('Quality summary:', summarize_quality(mock_translations))